object Solution {
  def nextBeautifulNumber(n: Int): Int = {
    // Precomputed numerically balanced numbers up to a certain range.
    // These are all numerically balanced numbers with digits 1 to 7 (since digits >7 can't appear that many times)
    // and length up to 7 digits (since n <= 10^6, but we go a bit beyond to be safe).
    // We generate them by backtracking all possible digit counts that satisfy the condition.

    import scala.collection.mutable.ArrayBuffer

    val res = ArrayBuffer[Int]()

    def backtrack(digit: Int, counts: Array[Int], totalLen: Int): Unit = {
      if (digit == 10) {
        if (totalLen > 0) {
          // Check if counts satisfy the numerically balanced condition:
          // For each digit d, either count[d] == 0 or count[d] == d
          var valid = true
          for (d <- 1 to 9) {
            if (counts(d) != 0 && counts(d) != d) {
              valid = false
            }
          }
          if (valid) {
            // Construct the number from counts
            val sb = new StringBuilder
            for (d <- 1 to 9) {
              for (_ <- 0 until counts(d)) {
                sb.append(d)
              }
            }
            val num = sb.toString.toInt
            res += num
          }
        }
        return
      }

      // For digit 0, count must be 0 because digit 0 cannot appear (0 times) or else it violates the condition.
      if (digit == 0) {
        backtrack(digit + 1, counts, totalLen)
      } else {
        // For digit d, count can be 0 or d
        // Try count = 0
        counts(digit) = 0
        backtrack(digit + 1, counts, totalLen)
        // Try count = digit (if totalLen + digit <= 10 to avoid too long numbers)
        if (totalLen + digit <= 10) {
          counts(digit) = digit
          backtrack(digit + 1, counts, totalLen + digit)
          counts(digit) = 0
        }
      }
    }

    backtrack(0, Array.fill(10)(0), 0)
    val sorted = res.sorted
    // Find the smallest numerically balanced number strictly greater than n
    sorted.find(_ > n).getOrElse(-1)
  }
}

